import{_ as t,o as a,c as s,ao as o}from"./chunks/framework.DcztfwHe.js";const k=JSON.parse('{"title":"BiotSavartBCs changes","description":"","frontmatter":{},"headers":[],"relativePath":"biotsavart.md","filePath":"biotsavart.md","lastUpdated":null}'),i={name:"biotsavart.md"};function r(n,e,h,c,l,d){return a(),s("div",null,[...e[0]||(e[0]=[o('<h1 id="BiotSavartBCs-changes" tabindex="-1">BiotSavartBCs changes <a class="header-anchor" href="#BiotSavartBCs-changes" aria-label="Permalink to &quot;BiotSavartBCs changes {#BiotSavartBCs-changes}&quot;">​</a></h1><p>The <code>-biotsavart</code> cases solve the pressure Poisson equation through <a href="https://github.com/WaterLily-jl/BiotSavartBCs.jl" target="_blank" rel="noreferrer">BiotSavartBCs.jl</a>&#39;s own <code>mom_project!</code> rather than WaterLily&#39;s <code>solver!</code>. A change that spans both packages, such as the stopping criterion of the Poisson solver, can only be measured by switching BiotSavartBCs together with WaterLily.</p><p>By default the benchmark environment follows the <code>main</code> branch of BiotSavartBCs (the <code>[sources]</code> entry of <code>Project.toml</code>). To pair each WaterLily ref with a BiotSavartBCs ref, pass <code>-bs</code> a list of BiotSavartBCs branches, tags or hashes, one per <code>-w</code> ref, and a local BiotSavartBCs clone with <code>-bsd</code> or <code>$BIOTSAVART_DIR</code>:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">./benchmark.sh</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -w</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;master poisson-rms-tol&quot;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -bs</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;main combined-tol&quot;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -bsd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ~/BiotSavartBCs.jl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -c</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> jelly-biotsavart</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -b</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> Array</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -t</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;1 4&quot;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -r</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 3</span></span></code></pre></div><p>Each run checks out the WaterLily ref first and then its BiotSavartBCs ref, since a BiotSavartBCs branch can need new WaterLily functions. A change in BiotSavartBCs alone is measured against a fixed WaterLily with <code>-w &quot;master master&quot; -bs &quot;main my-branch&quot;</code>.</p><h2 id="How-it-works" tabindex="-1">How it works <a class="header-anchor" href="#How-it-works" aria-label="Permalink to &quot;How it works {#How-it-works}&quot;">​</a></h2><ul><li><p><code>-bs</code> points the <code>[sources]</code> entry of <code>Project.toml</code> at the local clone and forces <code>-u true</code>. On exit, also after an error or an interrupt, the sweep restores <code>Project.toml</code>, <code>Manifest.toml</code> and the <code>gpu/</code> environments as they were, since Pkg would otherwise keep using the clone. On a clone that had no <code>Manifest.toml</code> before the sweep, this removes it again: the next <code>benchmark.sh</code> run installs it, but <code>compare.jl</code> needs <code>julia --project -e &#39;using Pkg; Pkg.instantiate()&#39;</code> first (the action does this).</p></li><li><p>A <code>-bs</code> run is tagged <code>&lt;WaterLily hash&gt;+bs&lt;BiotSavartBCs hash&gt;</code>, in the results and in the file and directory names, so runs that differ only in BiotSavartBCs stay apart.</p></li><li><p><code>compare.jl</code> shows such a run as e.g. <code>master (bs main)</code>, naming the BiotSavartBCs ref from the clone in <code>$BIOTSAVART_DIR</code>, and <code>--speedup_base</code> also accepts a BiotSavartBCs ref or hash.</p></li></ul><p>On <a href="./pull-requests">pull requests</a>, <code>-bs</code> works the same way: the action checks out BiotSavartBCs.jl itself, so the refs must exist on GitHub. For example, <code>/benchmark -w &quot;pr-123 pr-123&quot; -bs &quot;main my-branch&quot;</code> compares two BiotSavartBCs branches on the pull request&#39;s WaterLily.</p>',8)])])}const u=t(i,[["render",r]]);export{k as __pageData,u as default};
